/*
 * Vendored from ps2pdx/nertia at 58bd29ab (4fc06b12^), src/components/ButterflyRingParticles.tsx,
 * the nertia homepage hero, April 2026. Read-only specimen, three.js as it was (three 0.182.0, the
 * version nertia shipped): the same scene, camera, two point layers, rotation inertia, auto-rotation,
 * screen-space pointer repulsion, spring-back and wheel zoom with inertia.
 * Changes for this site: the vertices (public/butterfly-ring-vertices.json there) come from a lazily
 * imported module, ./butterfly-ring-vertices, generated by scripts/butterfly-vertices.py, instead of a
 * fetch; pointer events sit on the plate's canvas, not the window, and the pointer is measured against
 * the canvas; the wheel zooms only while the pointer is over the plate after a click into it, so page
 * scrolling is never captured; the loop runs only while `running` (near the viewport, tab visible) and
 * renders one still frame when `still`; the colour is the --particle token over the plate's own
 * background (additive in dark, normal in light, the original opacities), refreshed on a theme change;
 * the unused raycaster world point is left out.
 */
import { useEffect, useRef } from 'react';
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color, Group, Matrix4, NormalBlending, PerspectiveCamera, Points, PointsMaterial, Scene, Vector3, WebGLRenderer } from 'three';
import { getTheme } from '@/lib/theme';
import type { SpecimenProps } from './types';
import s from './specimens.module.css';

const config = { scale: 8, rotationSpeed: 0.0003, mouseInfluenceRadius: 1.2, mouseStrength: 0.15, returnSpeed: 0.04 };
const themeFor = (dark: boolean) => (dark
  ? { particleOpacity: 0.85, glowOpacity: 0.1, blending: AdditiveBlending }
  : { particleOpacity: 0.95, glowOpacity: 0.05, blending: NormalBlending });

const decode = (b64: string, scale: number) => {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const q = new Int16Array(bytes.buffer);
  const out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) out[i] = q[i] * scale;
  return out;
};

export default function ButterflyRing({ running, still }: SpecimenProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const runRef = useRef({ running, still });
  runRef.current = { running, still };
  const loopRef = useRef<{ animate: () => void } | null>(null);
  const rafRef = useRef(0);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    let isCleanedUp = false;
    let renderer: WebGLRenderer | null = null;
    let dispose = () => {};

    const initScene = async () => {
      const { VERTICES, SCALE } = await import('./butterfly-ring-vertices');
      if (isCleanedUp) return;

      const mouse = { x: 10, y: 10 };
      const drag = { isDragging: false, lastX: 0, lastY: 0, rotationX: Math.PI - Math.PI / 6, rotationY: Math.PI, velocityX: 0, velocityY: 0 };
      const zoom = { current: 16, target: 16 };
      let engaged = false;

      const w = () => container.clientWidth || 1, h = () => container.clientHeight || 1;
      const scene = new Scene();
      const camera = new PerspectiveCamera(50, w() / h(), 0.1, 1000);
      camera.position.set(0, 6, 16);
      camera.lookAt(0, 0, 0);

      try { renderer = new WebGLRenderer({ antialias: true, alpha: true }); } catch { return; }
      const r = renderer;
      r.setClearColor(0x000000, 0);
      r.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      r.setSize(w(), h());
      r.domElement.className = s.canvas;
      r.domElement.setAttribute('aria-hidden', 'true');
      container.appendChild(r.domElement);

      const positions = decode(VERTICES, SCALE * config.scale);
      const actualCount = positions.length / 3;
      const originalPositions = new Float32Array(positions);
      const velocities = new Float32Array(actualCount * 3);

      const geometry = new BufferGeometry();
      geometry.setAttribute('position', new BufferAttribute(positions, 3));
      const material = new PointsMaterial({ size: 0.08, transparent: true, sizeAttenuation: true });
      const glowGeometry = new BufferGeometry();
      glowGeometry.setAttribute('position', new BufferAttribute(positions.slice(), 3));
      const glowMaterial = new PointsMaterial({ size: 0.18, transparent: true, sizeAttenuation: true });
      const butterflyGroup = new Group();
      butterflyGroup.add(new Points(geometry, material));
      butterflyGroup.add(new Points(glowGeometry, glowMaterial));
      scene.add(butterflyGroup);

      const applyTheme = () => {
        const theme = themeFor(getTheme() === 'dark');
        const colour = new Color();
        try { colour.setStyle(getComputedStyle(container).getPropertyValue('--particle').trim() || '#2bf52b'); } catch { colour.set(0x2bf52b); }
        for (const [m, opacity] of [[material, theme.particleOpacity], [glowMaterial, theme.glowOpacity]] as const) {
          m.color.copy(colour); m.opacity = opacity; m.blending = theme.blending; m.needsUpdate = true;
        }
      };
      applyTheme();

      const particleWorldPos = new Vector3();
      const particleScreenPos = new Vector3();
      const forceDir = new Vector3();
      const localOrigin = new Vector3();
      const inverseMatrix = new Matrix4();

      const step = () => {
        if (!drag.isDragging) {
          drag.rotationX += drag.velocityX;
          drag.rotationY += drag.velocityY;
          drag.velocityX *= 0.95;
          drag.velocityY *= 0.95;
          if (Math.abs(drag.velocityY) < 0.0001) drag.rotationY += config.rotationSpeed;
        }
        butterflyGroup.rotation.y = drag.rotationY;
        butterflyGroup.rotation.x = drag.rotationX;
        zoom.current += (zoom.target - zoom.current) * 0.08;
        camera.position.z = zoom.current;

        const posAttr = geometry.attributes.position as BufferAttribute;
        const posArray = posAttr.array as Float32Array;
        const glowPosAttr = glowGeometry.attributes.position as BufferAttribute;
        const glowPosArray = glowPosAttr.array as Float32Array;

        butterflyGroup.updateMatrixWorld();
        camera.updateMatrixWorld();
        inverseMatrix.copy(butterflyGroup.matrixWorld).invert();
        localOrigin.set(0, 0, 0).applyMatrix4(inverseMatrix);

        for (let i = 0; i < actualCount; i++) {
          const i3 = i * 3;
          particleWorldPos.set(posArray[i3], posArray[i3 + 1], posArray[i3 + 2]).applyMatrix4(butterflyGroup.matrixWorld);
          particleScreenPos.copy(particleWorldPos).project(camera);
          const dx = particleScreenPos.x - mouse.x;
          const dy = particleScreenPos.y - mouse.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const screenInfluenceRadius = 0.3;
          if (!drag.isDragging && dist < screenInfluenceRadius && dist > 0.001) {
            const force = (1 - dist / screenInfluenceRadius) * config.mouseStrength;
            forceDir.set(dx, dy, 0).normalize().multiplyScalar(force * 0.02);
            forceDir.applyMatrix4(inverseMatrix).sub(localOrigin);
            velocities[i3] += forceDir.x;
            velocities[i3 + 1] += forceDir.y;
            velocities[i3 + 2] += forceDir.z + (Math.random() - 0.5) * force * 0.01;
          }
          posArray[i3] += velocities[i3];
          posArray[i3 + 1] += velocities[i3 + 1];
          posArray[i3 + 2] += velocities[i3 + 2];
          posArray[i3] += (originalPositions[i3] - posArray[i3]) * config.returnSpeed;
          posArray[i3 + 1] += (originalPositions[i3 + 1] - posArray[i3 + 1]) * config.returnSpeed;
          posArray[i3 + 2] += (originalPositions[i3 + 2] - posArray[i3 + 2]) * config.returnSpeed;
          velocities[i3] *= 0.94;
          velocities[i3 + 1] *= 0.94;
          velocities[i3 + 2] *= 0.94;
          glowPosArray[i3] = posArray[i3];
          glowPosArray[i3 + 1] = posArray[i3 + 1];
          glowPosArray[i3 + 2] = posArray[i3 + 2];
        }
        posAttr.needsUpdate = true;
        glowPosAttr.needsUpdate = true;
      };
      const render = () => r.render(scene, camera);

      const animate = () => {
        if (isCleanedUp) return;
        step();
        render();
        rafRef.current = runRef.current.running && !runRef.current.still ? requestAnimationFrame(animate) : 0;
      };
      loopRef.current = { animate };

      const onResize = () => {
        camera.aspect = w() / h();
        camera.updateProjectionMatrix();
        r.setSize(w(), h());
        if (!rafRef.current) render();
      };
      const canvas = r.domElement;
      const onPointerMove = (e: PointerEvent) => {
        const b = canvas.getBoundingClientRect();
        mouse.x = ((e.clientX - b.left) / b.width) * 2 - 1;
        mouse.y = -((e.clientY - b.top) / b.height) * 2 + 1;
        if (drag.isDragging) {
          const deltaX = e.clientX - drag.lastX;
          const deltaY = e.clientY - drag.lastY;
          drag.rotationY -= deltaX * 0.005;
          drag.rotationX += deltaY * 0.005;
          drag.velocityY = -deltaX * 0.005;
          drag.velocityX = deltaY * 0.005;
          drag.lastX = e.clientX;
          drag.lastY = e.clientY;
        }
      };
      const onPointerDown = (e: PointerEvent) => {
        engaged = true;
        drag.isDragging = true;
        drag.lastX = e.clientX;
        drag.lastY = e.clientY;
        canvas.setPointerCapture?.(e.pointerId);
      };
      const onPointerUp = (e: PointerEvent) => {
        drag.isDragging = false;
        canvas.releasePointerCapture?.(e.pointerId);
      };
      const onPointerLeave = () => {
        engaged = false;
        if (!drag.isDragging) { mouse.x = 10; mouse.y = 10; }
      };
      const onWheel = (e: WheelEvent) => {
        if (!engaged) return;
        e.preventDefault();
        zoom.target = Math.max(5, Math.min(40, zoom.target + e.deltaY * 0.02));
        if (!rafRef.current) { zoom.current = zoom.target; camera.position.z = zoom.current; render(); }
      };
      const onTheme = () => { applyTheme(); if (!rafRef.current) render(); };

      canvas.addEventListener('pointermove', onPointerMove);
      canvas.addEventListener('pointerdown', onPointerDown);
      canvas.addEventListener('pointerup', onPointerUp);
      canvas.addEventListener('pointercancel', onPointerUp);
      canvas.addEventListener('pointerleave', onPointerLeave);
      canvas.addEventListener('wheel', onWheel, { passive: false });
      const mo = new MutationObserver(onTheme);
      mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
      const mql = window.matchMedia?.('(prefers-color-scheme: dark)');
      mql?.addEventListener('change', onTheme);
      const ro = new ResizeObserver(onResize);
      ro.observe(container);

      dispose = () => {
        canvas.removeEventListener('pointermove', onPointerMove);
        canvas.removeEventListener('pointerdown', onPointerDown);
        canvas.removeEventListener('pointerup', onPointerUp);
        canvas.removeEventListener('pointercancel', onPointerUp);
        canvas.removeEventListener('pointerleave', onPointerLeave);
        canvas.removeEventListener('wheel', onWheel);
        mo.disconnect(); ro.disconnect();
        mql?.removeEventListener('change', onTheme);
        geometry.dispose(); glowGeometry.dispose(); material.dispose(); glowMaterial.dispose();
      };

      if (runRef.current.running && !runRef.current.still) animate();
      else { step(); render(); }
    };

    initScene().catch(() => {});

    return () => {
      isCleanedUp = true;
      cancelAnimationFrame(rafRef.current);
      rafRef.current = 0;
      loopRef.current = null;
      dispose();
      if (renderer) {
        if (container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
        renderer.dispose();
      }
    };
  }, []);

  useEffect(() => {
    const loop = loopRef.current;
    if (!loop) return;
    if (running && !still) { if (!rafRef.current) rafRef.current = requestAnimationFrame(loop.animate); }
    else if (rafRef.current) { cancelAnimationFrame(rafRef.current); rafRef.current = 0; }
  }, [running, still]);

  return <div ref={containerRef} data-part="butterfly-ring" className={s.fill} />;
}
